#!/usr/bin/env bash
# 把 workflow_dispatch 传入的参数注入到 Android 壳工程
# 用法: apply.sh <url> <app_name> <package> <icon_url> <splash_url> <splash_title> <app_version>
set -e

URL="$1"
APP_NAME="$2"
PACKAGE="$3"
ICON_URL="$4"
SPLASH_URL="$5"
SPLASH_TITLE="$6"
APP_VERSION="$7"

# 转义 sed 替换串里的特殊字符（& \ ），避免网址含 & 时注入出错
esc_sed() { printf '%s' "$1" | sed 's/[&\\]/\\&/g'; }
URL=$(esc_sed "$URL")
APP_NAME=$(esc_sed "$APP_NAME")
SPLASH_TITLE=$(esc_sed "$SPLASH_TITLE")

# 版本号：默认 1.0，非法时回退
if [ -z "$APP_VERSION" ] || ! echo "$APP_VERSION" | grep -qE '^[0-9]+\.[0-9]+$'; then
  APP_VERSION="1.0"
fi

# Android SDK 路径（gradle 读取）
echo "sdk.dir=$ANDROID_HOME" > local.properties

# ---- 包名：移动 MainActivity 到对应包路径，并替换声明 ----
PKG_PATH=$(echo "$PACKAGE" | tr '.' '/')
mkdir -p "app/src/main/java/$PKG_PATH"
mv -f "app/src/main/java/com/xgmod/web2app/MainActivity.java" "app/src/main/java/$PKG_PATH/MainActivity.java"
rm -rf "app/src/main/java/com/xgmod"

# MainActivity 的 package 声明 + 目标网址
sed -i "s/^package com\.xgmod\.web2app;/package $PACKAGE;/" "app/src/main/java/$PKG_PATH/MainActivity.java"
sed -i "s#__URL__#$URL#g" "app/src/main/java/$PKG_PATH/MainActivity.java"

# ---- AndroidManifest.xml ----
sed -i "s/package=\"com\.xgmod\.web2app\"/package=\"$PACKAGE\"/" app/src/main/AndroidManifest.xml
sed -i "s/__APP_NAME__/$APP_NAME/g" app/src/main/AndroidManifest.xml

# ---- app/build.gradle（namespace / applicationId / 版本号）----
sed -i "s/__PACKAGE__/$PACKAGE/g" app/build.gradle
sed -i "s/__VERSION_NAME__/$APP_VERSION/g" app/build.gradle

# ---- 开屏启动标题（activity_main.xml）----
sed -i "s/__SPLASH_TITLE__/$SPLASH_TITLE/g" app/src/main/res/layout/activity_main.xml

# ---- res/values/strings.xml（应用名）----
sed -i "s/__APP_NAME__/$APP_NAME/g" app/src/main/res/values/strings.xml

# ---- 图标：从 URL 下载写入 drawable/ic_launcher.png（失败则保留默认图标）----
mkdir -p app/src/main/res/drawable
if [ -n "$ICON_URL" ]; then
  curl -fsSL "$ICON_URL" -o app/src/main/res/drawable/ic_launcher.png || echo "warn: 图标下载失败，使用默认"
fi

# ---- 开屏壁纸：base64 解码写入 drawable/splash.png ----
# 用户没上传开屏时，用内置默认淡紫渐变图，保证 drawable/splash 资源始终存在（否则 Java 编译会报 R.drawable.splash 找不到）
DEFAULT_SPLASH_B64=''

mkdir -p app/src/main/res/drawable
if [ -n "$SPLASH_URL" ]; then
  curl -fsSL "$SPLASH_URL" -o app/src/main/res/drawable/splash.png || echo "warn: 开屏下载失败，使用默认"
else
  echo "$DEFAULT_SPLASH_B64" | base64 -d > app/src/main/res/drawable/splash.png
fi

echo "参数注入完成: package=$PACKAGE, name=$APP_NAME, url=$URL"
